 [('Stop retrying', 'Repeated tries from a new place extend the lock.'),
  ('Use a trusted network', 'Your home network or mobile data looks more normal than a public one.'),
  ('Mention the travel', 'A short line in the form explains the new location.')],
 ['A login from a new country.', 'A local SIM with a new number.', 'Public Wi-Fi or a hotel network.', 'A VPN used while travelling.'],
 ['Turn off any VPN and stop retrying.', 'Log in once from your usual network or data.', 'Use the unlock form and mention the travel.', 'Send us the message if the lock stays.'],
